steps.analogousExample:
/* Example of styling two sections */
section {
  position: absolute;
  width: 100%;
  height: 100%;
  transition: all 0.5s ease;
}

#view1 {
  background-color: #4a90e2;
  left: 0;
}

#view2 {
  background-color: #e24a4a;
  left: 100%;
}

/* Similar: applying a custom property to an element */
.header {
  view-transition-name: 'header';
}

